INSERT INTO `mystore_faq` VALUES (1,'What is ShopZone?','ShopZone is an online store for mobile parts, tools, and accessories at wholesale prices, with secure shopping, fast delivery, and easy returns.','general',0,1,'2026-04-07 06:26:37.880217','2026-04-07 06:26:37.880266'),(2,'How do I get started shopping?','Create a free account, browse categories, add items to cart, and checkout with your preferred payment method.','general',0,1,'2026-04-07 06:27:01.198423','2026-04-07 06:27:01.198457'),(3,'What are your shipping options and costs?','We offer standard shipping (3-7 days, free over ₹1000) and express (1-3 days, ₹99+). Track orders in your account dashboard.','shipping',0,1,'2026-04-07 06:27:37.408732','2026-04-07 06:27:37.408800'),(4,'Do you ship to my location?','Yes, across India via trusted partners like Delhivery or BlueDart. Enter your PIN code at checkout for rates.','shipping',0,1,'2026-04-07 06:28:45.007990','2026-04-07 06:28:45.008024'),(5,'What is your return policy?','7-day returns on unused items in original packaging. Initiate via My Account > Returns, and get full refund within 3-5 days post-approval.','returns',0,1,'2026-04-07 06:29:15.286970','2026-04-07 06:29:15.287008'),(6,'How do I request a refund?','Log in, go to Orders > Return Request, upload photos, and select reason. We\'ll review within 24 hours.','returns',0,1,'2026-04-07 06:29:44.595125','2026-04-07 06:29:44.595192'),(7,'What payment methods are accepted?','Credit/Debit cards, UPI, net banking, wallets (Paytm/PhonePe), and COD where available. All via secure gateways.','payment',0,1,'2026-04-07 06:30:10.070422','2026-04-07 06:30:10.070462'),(8,'Is my payment information safe?','Yes, we use PCI-DSS compliant encryption and don\'t store card details. See our Terms for details.','payment',0,1,'2026-04-07 06:30:50.209405','2026-04-07 06:30:50.209441'),(9,'How do I manage my account?','Update profile, addresses, wishlist, and orders in My Account. Enable notifications for updates.','account',0,1,'2026-04-07 06:31:13.382000','2026-04-07 06:31:13.382040'),(10,'Forgot password or need verification help?','Use \"Forgot Password\" on login, or check email/phone verifications in My Account. Contact support if issues persist.','account',0,1,'2026-04-07 06:31:37.974928','2026-04-07 06:31:37.974969'),(11,'How can I check product availability?','Stock levels show on product pages. Low stock items notify on order; backorders ship when available.','products',0,1,'2026-04-07 06:32:10.281078','2026-04-07 06:32:10.281113'),(12,'Are these genuine products?','All listed via verified sellers with quality checks. Read reviews and return if unsatisfied.','products',0,1,'2026-04-07 06:32:39.985178','2026-04-07 06:32:39.985240'),(13,'How long for delivery?','3-7 days','general',0,1,'2026-04-18 13:54:42.208783','2026-04-18 13:54:42.208888');
/*!40000 ALTER TABLE `mystore_faq` ENABLE KEYS */;
UNLOCK TABLES;

