  `created_at` datetime(6) NOT NULL,
  `order_id` bigint NOT NULL,
  `user_id` int NOT NULL,
  PRIMARY KEY (`id`),
  KEY `MyStore_refundrequest_order_id_a4b753f5_fk_MyStore_order_id` (`order_id`),
  KEY `MyStore_refundrequest_user_id_a6a891a3_fk_auth_user_id` (`user_id`),
  CONSTRAINT `MyStore_refundrequest_order_id_a4b753f5_fk_MyStore_order_id` FOREIGN KEY (`order_id`) REFERENCES `mystore_order` (`id`),
  CONSTRAINT `MyStore_refundrequest_user_id_a6a891a3_fk_auth_user_id` FOREIGN KEY (`user_id`) REFERENCES `auth_user` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
