  `is_active` tinyint(1) NOT NULL,
  `created_at` datetime(6) NOT NULL,
  `updated_at` datetime(6) NOT NULL,
  PRIMARY KEY (`id`),
  CONSTRAINT `mystore_returnpolicy_chk_1` CHECK ((`return_window_days` >= 0)),
  CONSTRAINT `mystore_returnpolicy_chk_2` CHECK ((`refund_percentage` >= 0))
