INSERT INTO `mystore_returnpolicy` VALUES (1,'Standard 7-Day Return Policy','Customers may request a return within 7 days of delivery for eligible items. Items must be unused, in original condition, and returned with original packaging, tags, accessories, and invoice. Refunds are processed after inspection and approved returns are credited to the original payment method within 5 to 7 business days. Return shipping may be charged for non-defective items, while defective, damaged, or wrongly delivered items qualify for free return support.',7,100,'Item must be unused and undamaged; original box, tags, accessories, manuals, and invoice must be included; return request must be raised within 7 days of delivery; non-returnable items include personal care products, innerwear, perishable goods, gift cards, and customized items; used or incomplete items may be rejected or may receive only a partial refund.','1. Log in to your account and open My Orders. 2. Select the delivered order and choose Return Request. 3. Pick the item, reason, and upload photos if the item is damaged or wrong. 4. Wait for approval from support. 5. Pack the item securely with all original contents. 6. Hand over the parcel to the pickup partner or ship as instructed. 7. After inspection, the refund is issued to the original payment method within 5 to 7 business days.',1,'2026-04-06 17:12:08.732170','2026-04-06 17:12:08.732205'),(2,'Electronics Strict Policy','Electronics require all accessories and original box. Strict inspection for damage/misuse.',7,100,'Must include charger, cables, manuals, box. No scratches, liquid damage, or account locks.','1. My Orders → Return Electronics 2. Upload unboxing photos 3. Approval within 24hrs 4. Free pickup 5. Full inspection required\",True',1,'2026-04-06 17:27:28.292435','2026-04-06 17:27:28.292466');
/*!40000 ALTER TABLE `mystore_returnpolicy` ENABLE KEYS */;
UNLOCK TABLES;

