INSERT INTO `mystore_termsofservice` VALUES (1,'Terms of Service','Terms of Service for ShopZone\r\n\r\nLast Updated: April 7, 2026\r\n\r\nWelcome to ShopZone (\"Platform\", \"we\", \"us\", \"our\"). These Terms of Service (\"Terms\") govern your access to and use of our website at shopzone.com (the \"Site\"), mobile app, and services (collectively, the \"Services\"). By registering, browsing, or purchasing, you agree to these Terms, our Privacy Policy, and applicable laws including the Information Technology Act, 2000, and Consumer Protection Act, 2019. If you disagree, do not use the Services.\r\n\r\n1. Eligibility and Accounts\r\n- You must be 18+ or have guardian consent.\r\n- Provide accurate info during registration; we may verify via email/phone/KYC.\r\n- Keep login credentials secure; you\'re responsible for account activity.\r\n- We may suspend/terminate accounts for violations.[web:11][web:18]\r\n\r\n2. Products and Orders\r\n- We sell mobile parts, tools, and accessories via verified sellers.\r\n- Prices exclude taxes/shipping; final at checkout.\r\n- Orders are offers; confirmation via email. We reserve right to cancel.\r\n- Stock shown as-is; backorders possible.[web:13][web:16]\r\n\r\n3. Payments and Invoices\r\n- Use secure methods: cards, UPI, wallets, COD.\r\n- All transactions PCI-DSS compliant; no liability for failed payments.\r\n- Invoices issued post-shipment; GST as applicable.[web:11]\r\n\r\n4. Shipping and Delivery\r\n- Estimated times; delays not our liability.\r\n- Inspect on delivery; report issues within 24 hours.\r\n- Risk transfers on handover to carrier.[web:12]\r\n\r\n5. Returns, Refunds, and Cancellations\r\n- See Return Policy (linked in footer).\r\n- Refunds within 7 days for eligible items, minus fees.\r\n- No refunds on custom/digital goods.[web:11]\r\n\r\n6. User Conduct\r\n- No illegal use, spam, fake reviews, or IP infringement.\r\n- Reviews must be genuine; we moderate/remove violations.\r\n- Prohibited: hacking, scraping without permission.[web:11][web:15]\r\n\r\n7. Intellectual Property\r\n- Site content ours or licensors\'; no copying/reproduction.\r\n- User content (reviews) grants us non-exclusive license.[web:11]\r\n\r\n8. Limitation of Liability\r\n- Services \"as-is\"; no warranties.\r\n- Max liability: order value.\r\n- Not liable for indirect damages, seller errors, or force majeure.[web:11][web:12]\r\n\r\n9. Termination\r\n- We may end access anytime for cause.\r\n- Sections on liability/IP survive termination.[web:11]\r\n\r\n10. Governing Law\r\n- Laws of India; disputes in Surat, Gujarat courts.\r\n- Arbitration per Arbitration Act, 1996 if needed.[web:14][web:18]\r\n\r\n11. Changes\r\n- We may update Terms; continued use = acceptance.\r\n- Check footer link regularly.\r\n\r\n12. Contact\r\n- Email: support@shopzone.com | Phone: +91-93244-99448 | Address: Atlanta Business Hub, Shop No 77, Vesu, Surat, Gujarat.\r\n\r\nBy using ShopZone, you acknowledge agreement.','1.0','2026-04-07',1,'2026-04-07 06:39:14.507844','2026-04-07 06:39:14.507877');
